const d={"truong-lop":{name:"Trường lớp của em",icon:"🏫"},"ban-than":{name:"Khám phá bản thân",icon:"🌟"},"ren-luyen":{name:"Rèn luyện bản thân",icon:"💪"},"gia-dinh":{name:"Gia đình – bạn bè",icon:"🏡"},"cong-dong":{name:"Cộng đồng quanh em",icon:"🤝"},"thien-nhien":{name:"Thiên nhiên – môi trường",icon:"🌳"},"nghe-nghiep":{name:"Tìm hiểu nghề nghiệp",icon:"🧑‍🔧"},"an-toan":{name:"An toàn cho em",icon:"🛡️"}},u=["truong-lop","truong-lop","truong-lop","ban-than","ban-than","ban-than","ban-than","ren-luyen","gia-dinh","gia-dinh","truong-lop","truong-lop","ren-luyen","ren-luyen","an-toan","an-toan","ren-luyen","ren-luyen","gia-dinh","gia-dinh","cong-dong","cong-dong","cong-dong","cong-dong","gia-dinh","thien-nhien","thien-nhien","thien-nhien","thien-nhien","nghe-nghiep","nghe-nghiep","nghe-nghiep","nghe-nghiep","an-toan","ban-than"],l=[["🎒","Chuẩn bị cặp sách","Bé tự xếp cặp sách cho ngày mai đi học.",["Bé lấy hết đồ trong cặp ra bàn.","Bé cùng ba mẹ xem thời khóa biểu ngày mai.","Bé xếp sách vở, bút, thước vào cặp.","Bé đặt cặp ở chỗ dễ thấy gần cửa."],"Ngày mai con học những môn gì?","life-places"],["🏫","Kể về trường mới","Bé kể cho ba mẹ nghe về trường lớp của mình.",["Bé nói tên trường và tên lớp của mình.","Bé kể tên cô giáo và một bạn mới quen.","Bé vẽ cổng trường hoặc lớp học ra giấy.","Ba mẹ viết giúp tên trường dưới bức tranh."],"Ở trường, con thích nơi nào nhất?","art-step"],["👋","Lời chào lễ phép","Bé tập chào hỏi người lớn và bạn bè.",["Ba mẹ và bé đóng vai gặp cô giáo ở cổng trường.","Bé tập nói: Con chào cô ạ.","Bé tập chào bạn và vẫy tay thân thiện.","Ngày mai bé chào cô và một bạn ở lớp."],"Hôm nay con đã chào những ai?","life-kind"],["🪞","Em là ai","Bé giới thiệu về bản thân mình.",["Bé soi gương và nói tên, tuổi của mình.","Bé kể ba điều mình thích.","Bé vẽ chân dung mình ra giấy.","Ba mẹ dán bức tranh lên tường cho cả nhà xem."],"Con thích điều gì nhất ở bản thân mình?"],["✋","Bàn tay của em","Bé biết bàn tay giúp mình làm được nhiều việc.",["Bé đặt tay lên giấy, ba mẹ vẽ viền quanh bàn tay.","Bé đếm năm ngón tay và tô màu bức tranh.","Bé kể ba việc bàn tay giúp bé làm mỗi ngày.","Bé rửa tay sạch sẽ theo sáu bước."],"Hôm nay bàn tay con đã làm được việc tốt gì?","life-handwash"],["😊","Cảm xúc của em","Bé gọi tên được các cảm xúc vui, buồn, giận, sợ.",["Ba mẹ và bé thi làm mặt vui, buồn, giận, sợ.","Bé đoán cảm xúc trên gương mặt ba mẹ.","Bé kể một lần mình thấy rất vui.","Cả nhà hít thở thật chậm ba lần như khi thấy giận."],"Khi buồn, con muốn ba mẹ làm gì cho con?","life-feel"],["👂","Năm giác quan","Bé dùng mắt, tai, mũi, lưỡi, da để khám phá đồ vật.",["Bé ngồi yên, ba mẹ bịt mắt bé bằng khăn mềm.","Bé sờ và đoán ba đồ vật quen thuộc trong nhà.","Bé ngửi và đoán mùi một loại quả.","Bé nói giác quan nào đã giúp mình đoán đúng."],"Con dùng giác quan nào để nghe nhạc?","sci-senses"],["👕","Tự mặc quần áo","Bé tự mặc quần áo và cài cúc áo.",["Bé chọn bộ quần áo cho ngày mai.","Bé tập cài và mở cúc áo năm lần.","Bé tự mặc áo, mặc quần và đi dép.","Bé gấp bộ đồ đã thay để vào giỏ."],"Khi mặc quần áo, việc nào con thấy khó nhất?","life-routine"],["🤝","Người bạn của em","Bé kể về một người bạn và nói lời hay với bạn.",["Bé kể tên một người bạn ở lớp.","Bé kể điều mình thích ở bạn ấy.","Bé vẽ một món quà nhỏ tặng bạn.","Ngày mai bé tặng tranh và nói: Mình rất vui được làm bạn với cậu."],"Con và bạn thường chơi trò gì?"],["🧸","Cùng chơi, cùng chia sẻ","Bé tập chờ đến lượt và chia sẻ đồ chơi.",["Ba mẹ và bé chơi một trò chơi lần lượt.","Mỗi người chờ đến lượt mình mới chơi.","Bé chia đồ chơi để mọi người cùng chơi.","Chơi xong, mọi người nói lời cảm ơn nhau."],"Khi chờ đến lượt, con thấy thế nào?","life-kind"],["💐","Tấm thiệp tặng cô","Bé làm thiệp cảm ơn thầy cô nhân ngày 20 tháng 11.",["Bé gấp đôi một tờ giấy làm thiệp.","Bé vẽ bông hoa hoặc trái tim lên mặt trước.","Ba mẹ viết giúp lời cảm ơn, bé tô theo.","Bé tự tay tặng thiệp cho thầy cô."],"Con muốn cảm ơn thầy cô điều gì?","art-collage"],["📚","Góc học tập gọn gàng","Bé sắp xếp góc học tập của mình.",["Bé lau bàn học bằng khăn ẩm.","Bé xếp sách vở thành chồng ngay ngắn.","Bé cho bút vào hộp bút hoặc vào cốc.","Bé cất đồ chơi về đúng chỗ."],"Bàn học gọn gàng giúp con điều gì?","life-tidy"],["🪥","Đánh răng thật sạch","Bé tự đánh răng đúng cách vào buổi sáng và buổi tối.",["Bé lấy một chút kem đánh răng bằng hạt đậu lên bàn chải.","Bé chải mặt ngoài, mặt trong và mặt nhai của răng.","Bé đếm chậm đến hai mươi cho mỗi hàm răng.","Bé súc miệng và để bàn chải về đúng chỗ."],"Vì sao mình phải đánh răng trước khi đi ngủ?","life-dentist"],["⏰","Giờ nào việc nấy","Bé sắp xếp các việc buổi tối theo thứ tự.",["Bé kể các việc buổi tối: ăn cơm, tắm, học bài, đánh răng, đi ngủ.","Bé vẽ mỗi việc vào một mẩu giấy nhỏ.","Bé xếp các mẩu giấy theo đúng thứ tự.","Tối nay bé làm theo thứ tự đã xếp."],"Việc nào con làm ngay trước khi đi ngủ?","life-routine"],["🚦","Đèn giao thông","Bé nhớ ý nghĩa của đèn xanh, đèn vàng, đèn đỏ.",["Bé vẽ ba vòng tròn màu đỏ, vàng, xanh lên giấy.","Ba mẹ nói: đèn đỏ dừng lại, đèn vàng đi chậm lại, đèn xanh được đi.","Ba mẹ chỉ vào từng màu, bé làm động tác dừng lại hoặc bước đi.","Bé nhắc lại: qua đường phải nắm tay người lớn."],"Gặp đèn đỏ thì mình phải làm gì?","life-crossing"],["🔌","Đồ vật nguy hiểm trong nhà","Bé nhận ra đồ vật nguy hiểm và tránh xa.",["Ba mẹ và bé cùng đi một vòng quanh nhà.","Ba mẹ chỉ ổ điện, bếp, dao kéo, bé nói: con không chạm vào.","Bé vẽ các đồ vật nguy hiểm và gạch một dấu chéo.","Bé nhắc lại: thấy nguy hiểm thì gọi người lớn."],"Nếu thấy dây điện bị hở, con sẽ làm gì?","life-safe"],["🍚","Bữa cơm ngoan","Bé tự xúc cơm và ăn đủ các món.",["Bé rửa tay trước khi ăn.","Bé mời cả nhà trước bữa cơm.","Bé tự xúc cơm và ăn cả rau.","Ăn xong, bé mang bát của mình ra chỗ rửa."],"Hôm nay con đã ăn loại rau nào?","life-dishes"],["🛏️","Gấp chăn gọn gàng","Bé tự gấp chăn và xếp gối sau khi ngủ dậy.",["Ba mẹ làm mẫu cách gấp chăn làm đôi rồi gấp tiếp làm tư.","Bé tập gấp chăn của mình.","Bé đặt gối ngay ngắn ở đầu giường.","Cả nhà khen bé khi giường đã gọn gàng."],"Sáng nay con đã tự gấp chăn chưa?","life-tidy"],["👨‍👩‍👧","Gia đình của em","Bé giới thiệu các thành viên trong gia đình.",["Bé kể tên từng người trong nhà.","Bé vẽ bức tranh cả nhà ở bên nhau.","Bé kể một việc mỗi người hay làm cho cả nhà.","Bé ôm từng người và nói: Con yêu cả nhà."],"Con thích làm gì cùng cả nhà nhất?"],["🧹","Phụ giúp việc nhà","Bé làm một việc nhà vừa sức.",["Bé chọn một việc: nhặt rau, lau bàn hoặc tưới cây.","Ba mẹ làm mẫu, bé làm theo.","Bé làm xong và tự kiểm tra lại.","Cả nhà nói lời cảm ơn bé."],"Làm xong việc nhà, con thấy thế nào?","life-garden"],["🧧","Đón Tết cùng gia đình","Bé biết vài phong tục của ngày Tết.",["Ba mẹ kể cho bé nghe về Tết Nguyên đán.","Bé kể tên một món ăn ngày Tết.","Bé tập nói một câu chúc Tết người thân.","Bé giúp ba mẹ lau dọn một góc nhà đón Tết."],"Con thích điều gì nhất trong ngày Tết?","vn-holiday"],["🏘️","Hàng xóm thân thiện","Bé biết chào hỏi và quan tâm hàng xóm.",["Bé kể tên một nhà hàng xóm mà bé biết.","Ba mẹ và bé đóng vai gặp hàng xóm, bé tập chào.","Bé cùng ba mẹ vẽ những ngôi nhà gần nhà mình.","Lần tới gặp hàng xóm, bé lễ phép chào hỏi."],"Gần nhà mình có những ai?"],["🗑️","Bỏ rác đúng nơi","Bé biết giữ nơi công cộng sạch đẹp.",["Ba mẹ kể nơi công cộng là gì: công viên, đường phố, chợ.","Bé nhặt giấy vụn trong phòng và bỏ vào thùng rác.","Bé tập nói: Con bỏ rác đúng nơi.","Bé hứa không xả rác khi đi chơi."],"Nếu không có thùng rác ở gần, con sẽ làm gì?","life-trash"],["🇻🇳","Lá cờ Tổ quốc","Bé nhận biết lá cờ đỏ sao vàng.",["Ba mẹ cho bé xem hình lá cờ Việt Nam.","Bé vẽ và tô lá cờ đỏ sao vàng.","Bé đếm cánh ngôi sao: có năm cánh.","Bé đứng nghiêm như khi chào cờ ở trường."],"Lá cờ Tổ quốc có những màu gì?","vn-symbols"],["🌷","Quà tặng ngày 8 tháng 3","Bé làm quà tặng mẹ, bà, cô hoặc chị nhân ngày 8 tháng 3.",["Bé chọn người mình muốn tặng quà.","Bé vẽ và tô một bông hoa thật đẹp.","Bé tập nói một lời chúc ngắn.","Bé tặng hoa và ôm người ấy thật chặt."],"Con muốn chúc điều gì cho người được tặng quà?","art-collage"],["🌱","Gieo hạt đậu","Bé gieo hạt và theo dõi hạt nảy mầm.",["Bé lót bông hoặc giấy ăn ẩm vào một cái cốc.","Bé đặt ba hạt đậu lên trên.","Bé để cốc gần cửa sổ có ánh sáng.","Mỗi ngày bé xem hạt và nhỏ thêm vài giọt nước."],"Con đoán mấy ngày nữa hạt sẽ nảy mầm?","sci-grow"],["🐜","Con vật quanh nhà","Bé quan sát con vật nhỏ quanh nhà.",["Bé cùng ba mẹ tìm một con vật nhỏ: con kiến, con chim, con mèo hoặc con cá.","Bé quan sát từ xa, không chạm vào con vật.","Bé kể con vật có mấy chân, có màu gì.","Bé vẽ con vật đó ra giấy."],"Lúc con nhìn thấy, con vật đó đang làm gì?","vn-farm"],["☀️","Bầu trời hôm nay","Bé quan sát thời tiết mỗi ngày.",["Bé nhìn qua cửa sổ xem trời nắng, mưa hay nhiều mây.","Bé vẽ hình thời tiết vào một tờ lịch giấy.","Bé chọn quần áo hợp với thời tiết.","Cuối tuần, bé đếm số ngày nắng và ngày mưa."],"Trời mưa thì con cần mang theo gì?","sci-weather"],["🚿","Tiết kiệm nước","Bé biết khóa vòi nước khi không dùng.",["Ba mẹ chỉ cho bé các vòi nước trong nhà.","Bé khóa vòi trong lúc xoa xà phòng khi rửa tay.","Bé dùng cốc đựng nước khi đánh răng.","Bé nhắc cả nhà khóa chặt vòi nước."],"Vì sao mình phải tiết kiệm nước?","life-handwash"],["👩‍💼","Nghề của người thân","Bé biết công việc của người thân trong nhà.",["Bé hỏi người lớn trong nhà: Ba mẹ làm nghề gì?","Người lớn kể một việc mình làm mỗi ngày.","Bé đóng vai làm nghề đó trong năm phút.","Bé vẽ người thân đang làm việc."],"Công việc của người thân giúp ích gì cho mọi người?"],["🧑‍⚕️","Bác sĩ nhí","Bé đóng vai bác sĩ và biết ơn người chăm sóc sức khỏe.",["Bé dùng một sợi dây làm ống nghe.","Bé khám cho gấu bông: nghe tim, xem họng.","Bé dặn gấu bông uống nước và ngủ sớm.","Bé kể điều mình biết về công việc của bác sĩ."],"Khi bị ốm, ai đã giúp con khỏe lại?","life-dentist"],["👨‍🌾","Hạt gạo của bác nông dân","Bé biết hạt gạo do bác nông dân vất vả làm ra.",["Ba mẹ cho bé xem và sờ hạt gạo.","Ba mẹ kể: lúa được gieo, cấy, gặt rồi xay thành gạo.","Bé xếp vài hạt gạo thành hình bông hoa trên giấy.","Bé hứa ăn hết cơm, không bỏ phí."],"Vì sao mình không nên bỏ phí cơm?","life-garden"],["🧑‍🚒","Chú lính cứu hỏa","Bé biết số điện thoại cứu hỏa là 114.",["Ba mẹ kể về công việc của lính cứu hỏa.","Bé tập nhớ số 114 bằng cách vỗ tay theo từng số.","Bé học câu: Thấy cháy, con chạy ra ngoài và gọi người lớn.","Bé vẽ chiếc xe cứu hỏa màu đỏ."],"Thấy khói hoặc lửa, con sẽ làm gì?","life-sos"],["🏊","Mùa hè an toàn","Bé biết tránh xa ao, hồ, sông khi không có người lớn.",["Ba mẹ kể những nơi có nước sâu: ao, hồ, sông, bể nước.","Bé nhắc lại: chỉ chơi gần nước khi có người lớn đi cùng.","Bé tập đội mũ trước khi ra nắng.","Bé vẽ một bức tranh mùa hè an toàn."],"Muốn đi bơi, con cần đi cùng ai?","life-safe"],["🏅","Em đã lớn","Bé nhìn lại những điều mình làm được trong năm học.",["Bé xem lại vở và tranh vẽ từ đầu năm học.","Bé kể ba việc bây giờ mình đã tự làm được.","Bé chọn một điều muốn học thêm trong hè.","Cả nhà vỗ tay chúc mừng bé lên lớp 2."],"Năm học này, con tự hào nhất về điều gì?"]],b=[["📅","Thời gian biểu của em","Bé cùng ba mẹ lập thời gian biểu cho một ngày đi học.",["Bé kể các việc từ lúc ngủ dậy đến lúc đi ngủ.","Ba mẹ giúp bé ghi giờ cho từng việc.","Bé trang trí thời gian biểu và dán ở góc học tập.","Mỗi tối, bé đánh dấu những việc đã làm."],"Việc nào trong thời gian biểu con thấy khó làm đúng giờ?","life-routine"],["📋","Nội quy của lớp, của nhà","Bé hiểu vì sao lớp học và gia đình cần có nội quy.",["Bé kể ba điều trong nội quy lớp mình.","Ba mẹ và bé cùng đặt ba điều nội quy nhỏ cho gia đình.","Bé viết hoặc vẽ nội quy lên giấy.","Cả nhà cùng hứa làm theo nội quy."],"Nếu không có nội quy, lớp học sẽ ra sao?"],["🤗","Làm quen bạn mới","Bé tập cách làm quen và giúp đỡ bạn mới.",["Ba mẹ đóng vai bạn mới vào lớp.","Bé tập giới thiệu tên mình và hỏi tên bạn.","Bé rủ bạn cùng chơi một trò chơi.","Ngày mai bé thử làm quen với một bạn ở lớp."],"Con sẽ giúp bạn mới như thế nào?","life-kind"],["🌟","Điểm mạnh của em","Bé nhận ra những việc mình làm tốt.",["Bé nghĩ và kể ba việc mình làm tốt.","Ba mẹ kể thêm một điểm mạnh mà ba mẹ thấy ở bé.","Bé vẽ một ngôi sao và ghi một điểm mạnh vào mỗi cánh.","Bé dán ngôi sao ở góc học tập."],"Con muốn giỏi thêm việc gì nữa?"],["📏","Em lớn lên từng ngày","Bé thấy cơ thể mình thay đổi khi lớn lên.",["Bé đứng sát tường, ba mẹ dán một mẩu giấy đánh dấu chiều cao.","Bé nghe ba mẹ kể chuyện ngày bé còn nhỏ.","Bé ướm thử một bộ quần áo cũ để thấy mình đã lớn.","Bé kể một việc trước đây chưa làm được mà nay đã làm được."],"Con cần làm gì để lớn lên khỏe mạnh?"],["😌","Bình tĩnh khi tức giận","Bé biết cách làm dịu cơn giận.",["Bé kể một lần mình thấy tức giận.","Ba mẹ và bé tập hít vào đếm đến bốn, thở ra đếm đến bốn.","Bé chọn một cách làm dịu: uống nước, ôm gấu bông hoặc vẽ tranh.","Bé tập nói: Con đang giận, con cần bình tĩnh một chút."],"Lần tới khi giận, con sẽ thử cách nào?","life-feel"],["🎨","Sở thích của em","Bé chia sẻ sở thích và thử một sở thích mới.",["Bé kể những việc mình thích làm lúc rảnh.","Bé chọn một việc thích nhất và làm cùng ba mẹ mười phút.","Bé thử một việc mới: gấp giấy, hát hoặc kể chuyện.","Bé nói cảm nhận của mình sau khi thử."],"Con có muốn tiếp tục sở thích mới không?","art-step"],["🎒","Tự chuẩn bị đồ dùng học tập","Bé tự kiểm tra đồ dùng học tập mỗi tối.",["Bé làm một danh sách đồ dùng cần mang đi học.","Bé đọc danh sách và kiểm tra cặp.","Bé kiểm tra bút chì, tẩy và thước.","Bé đánh dấu vào danh sách khi đã xong."],"Nếu quên đồ dùng học tập, con sẽ làm gì?","life-places"],["💬","Lời xin lỗi và lời cảm ơn","Bé biết nói lời xin lỗi, lời cảm ơn đúng lúc.",["Ba mẹ kể hai tình huống nhỏ ở lớp.","Bé chọn nói lời xin lỗi hay lời cảm ơn cho từng tình huống.","Bé và ba mẹ đóng vai lại tình huống đó.","Hôm nay bé nói lời cảm ơn với ba người."],"Khi con nói lời xin lỗi, bạn sẽ thấy thế nào?","life-kind"],["🧩","Giúp bạn khi bạn cần","Bé biết quan tâm, giúp đỡ bạn bè.",["Bé kể một lần bạn đã giúp mình.","Bé nghĩ ba cách giúp bạn ở lớp.","Bé và ba mẹ đóng vai giúp một bạn quên mang bút.","Ngày mai bé thử giúp một bạn một việc nhỏ."],"Tuần này con đã giúp bạn việc gì?","life-kind"],["🌸","Biết ơn thầy cô","Bé bày tỏ lòng biết ơn thầy cô nhân ngày Nhà giáo Việt Nam.",["Bé kể một điều thầy cô đã dạy mình.","Bé làm một tấm thiệp hoặc một bông hoa giấy.","Bé viết một câu cảm ơn lên thiệp.","Bé tặng thiệp và nói lời chúc thầy cô."],"Con sẽ làm gì để thầy cô vui?","art-collage"],["🧽","Trực nhật ở nhà","Bé biết giữ lớp học và nhà cửa sạch sẽ.",["Bé kể các việc trực nhật ở lớp.","Ở nhà, bé lau bàn và xếp ghế ngay ngắn.","Bé nhặt giấy vụn bỏ vào thùng rác.","Bé ngắm lại căn phòng và kể những việc mình đã làm."],"Lớp học sạch sẽ giúp mọi người thế nào?","life-tidy"],["🧼","Giữ cơ thể sạch sẽ","Bé tự giữ vệ sinh cơ thể hằng ngày.",["Bé kể các việc giữ sạch cơ thể: tắm, gội đầu, rửa tay, cắt móng tay.","Bé tự rửa mặt và lau khô bằng khăn của mình.","Bé tập rửa tay sáu bước trước bữa ăn.","Bé để khăn và bàn chải về đúng chỗ của mình."],"Vì sao mỗi người nên dùng khăn riêng?","life-handwash"],["🐷","Tiết kiệm đồ dùng","Bé biết giữ gìn và tiết kiệm đồ dùng.",["Bé kiểm tra hộp bút xem đồ nào còn dùng được.","Bé dùng nốt mặt giấy còn trống để vẽ.","Bé vuốt phẳng những góc vở bị quăn.","Bé kể một cách tiết kiệm tiền như bỏ heo đất."],"Đồ dùng nào con muốn giữ gìn cẩn thận hơn?","life-save"],["🚸","Đi bộ an toàn","Bé biết đi bộ trên vỉa hè và qua đường an toàn.",["Ba mẹ vẽ con đường, vỉa hè và vạch kẻ cho người đi bộ lên giấy.","Bé chỉ chỗ đi bộ an toàn trên hình vẽ.","Bé tập: dừng lại, nhìn bên trái, nhìn bên phải, nắm tay người lớn.","Lần sau ra đường, bé nhắc lại các bước này."],"Vì sao không được chạy qua đường?","life-crossing"],["🙅","Nói không với người lạ","Bé biết cách ứng xử khi người lạ rủ đi theo.",["Ba mẹ kể một tình huống: người lạ cho kẹo và rủ đi chơi.","Bé tập nói to: Không, con không đi.","Bé tập chạy về chỗ người lớn quen biết.","Bé học thuộc số điện thoại của ba hoặc mẹ."],"Người lạ rủ đi, con sẽ nói gì và làm gì?","life-sos"],["🥦","Bữa ăn đủ chất","Bé biết ăn đủ các loại thức ăn.",["Bé kể các món trong bữa cơm hôm nay.","Ba mẹ chỉ cho bé món nào là rau, món nào là thịt cá, món nào là cơm.","Bé vẽ một đĩa ăn có đủ rau, cơm và thịt cá.","Bé thử ăn thêm một miếng rau."],"Tuần này con muốn thử ăn món rau nào?","life-chef"],["💤","Ngủ đủ giấc","Bé đi ngủ đúng giờ để ngày mai khỏe khoắn.",["Bé cùng ba mẹ chọn giờ đi ngủ.","Trước giờ ngủ, bé tắt ti vi và cất đồ chơi.","Bé đánh răng và chọn một câu chuyện ngắn để nghe.","Bé tự đánh dấu những ngày mình ngủ đúng giờ."],"Sáng nay thức dậy, con có thấy khỏe không?","life-routine"],["📸","Kỉ niệm gia đình","Bé lắng nghe và kể lại một kỉ niệm vui của gia đình.",["Ba mẹ kể một kỉ niệm vui của cả nhà.","Bé kể lại kỉ niệm đó bằng lời của mình.","Bé vẽ tranh về kỉ niệm ấy.","Cả nhà cùng đặt tên cho bức tranh."],"Cuối tuần này, con muốn cả nhà cùng làm gì?"],["🍽️","Dọn mâm cơm","Bé giúp dọn bữa cơm gia đình.",["Bé rửa tay sạch sẽ.","Bé xếp bát, đũa, thìa cho đủ mọi người.","Bé mời mọi người vào ăn cơm.","Ăn xong, bé giúp lau bàn."],"Con cần xếp bao nhiêu đôi đũa cho cả nhà?","life-dishes"],["🏮","Phong tục ngày Tết","Bé biết vài phong tục ngày Tết của người Việt.",["Ba mẹ kể về chúc Tết, mừng tuổi và gói bánh chưng.","Bé tập một lời chúc Tết ngắn.","Bé vẽ một cành đào hoặc cành mai.","Bé giúp ba mẹ xếp hoa quả lên đĩa."],"Ngày Tết, con muốn chúc người thân điều gì?","vn-holiday"],["🙋","Những người làm việc quanh em","Bé biết ơn những người làm việc ở nơi mình sống.",["Bé kể những người làm việc gần nhà: bác bảo vệ, cô bán hàng, cô lao công.","Bé nói một việc tốt mà mỗi người đã làm.","Bé tập nói lời cảm ơn khi được giúp đỡ.","Lần tới gặp, bé chào và cảm ơn họ."],"Nếu không có cô lao công, đường phố sẽ ra sao?"],["🌳","Giữ gìn sân chơi chung","Bé biết bảo vệ nơi công cộng.",["Bé kể những gì có ở công viên hoặc sân chơi gần nhà.","Ba mẹ và bé nói những việc nên làm và không nên làm ở đó.","Bé vẽ biển nhắc: Không bẻ cây, không xả rác.","Lần tới đi chơi, bé tự mang rác của mình bỏ vào thùng."],"Con đã thấy ai làm việc tốt ở sân chơi?","life-trash"],["🎶","Bài hát về quê hương","Bé hát một bài hát về quê hương, đất nước.",["Ba mẹ hát cho bé nghe một bài hát thiếu nhi về quê hương.","Bé hát theo từng câu.","Bé vỗ tay theo nhịp bài hát.","Bé hát lại cho cả nhà nghe."],"Bài hát nói về điều gì?","mus-rhythm"],["💝","Ngày 8 tháng 3 yêu thương","Bé làm việc tốt tặng mẹ, bà, chị hoặc cô nhân ngày 8 tháng 3.",["Bé chọn người mình muốn tặng quà.","Bé làm một tấm thiệp có hình bông hoa.","Bé làm giúp người ấy một việc nhà.","Bé tặng thiệp và nói lời chúc."],"Người ấy vui thế nào khi nhận quà?","art-collage"],["🌿","Chăm một chậu cây","Bé nhận chăm sóc một chậu cây nhỏ.",["Bé chọn một chậu cây trong nhà hoặc gieo hạt vào cốc đất.","Bé tưới nước vừa đủ, không để cây bị úng.","Bé đặt cây ở chỗ có ánh sáng.","Bé đánh dấu những ngày tưới cây trên tờ lịch."],"Cây cần những gì để lớn lên?","sci-grow"],["🐦","Yêu thương con vật","Bé biết yêu thương và bảo vệ con vật.",["Bé kể về con vật mình yêu thích.","Ba mẹ kể những việc làm con vật bị đau hoặc sợ hãi.","Bé vẽ tranh nhắc mọi người không bắt chim, không trêu chó mèo.","Nếu nhà có thú cưng, bé cùng người lớn cho thú cưng ăn."],"Vì sao không nên trêu chọc con vật?","vn-farm"],["🍂","Các mùa trong năm","Bé biết thời tiết thay đổi theo mùa.",["Ba mẹ kể: miền Bắc có bốn mùa, miền Nam có mùa mưa và mùa khô.","Bé nói bây giờ trời đang nóng hay lạnh.","Bé chọn quần áo hợp với thời tiết hôm nay.","Bé vẽ cảnh bầu trời hôm nay."],"Con thích thời tiết như thế nào nhất?","sci-weather"],["♻️","Đồ cũ thành đồ mới","Bé dùng lại đồ cũ trong nhà.",["Bé tìm một hộp giấy hoặc một chai nhựa đã dùng xong.","Bé cùng ba mẹ rửa sạch hoặc lau khô.","Bé dán giấy màu hoặc vẽ trang trí để làm hộp bút.","Bé đặt món đồ mới ở góc học tập."],"Trong nhà còn đồ cũ nào có thể dùng lại?","life-trash"],["🛠️","Đồ nghề của các nghề","Bé biết mỗi nghề có đồ dùng riêng.",["Ba mẹ nói tên một nghề, bé đoán đồ nghề.","Đổi lại: bé nói tên đồ nghề, ba mẹ đoán nghề.","Bé vẽ một nghề và đồ nghề của nghề đó.","Bé kể nghề đó giúp ích gì cho mọi người."],"Đầu bếp cần những đồ dùng gì?","life-chef"],["🧑‍🏫","Một ngày làm cô giáo","Bé đóng vai cô giáo và hiểu công việc dạy học.",["Bé chuẩn bị bài dạy: một chữ cái hoặc một phép tính.","Bé dạy ba mẹ hoặc gấu bông trong năm phút.","Ba mẹ đóng vai học trò và giơ tay phát biểu.","Bé kể điều khó nhất khi làm cô giáo."],"Con có muốn làm cô giáo không, vì sao?"],["🧑‍🍳","Đầu bếp nhí","Bé phụ giúp làm một món ăn đơn giản không cần dùng bếp.",["Bé rửa tay và mặc một chiếc áo cũ để khỏi bẩn.","Bé cùng người lớn rửa rau hoặc rửa quả.","Bé xếp quả đã được người lớn cắt sẵn ra đĩa.","Bé mời cả nhà cùng thưởng thức."],"Đầu bếp cần làm gì để món ăn sạch sẽ?","life-chef"],["🩺","Bác sĩ và y tá","Bé biết công việc của bác sĩ và y tá.",["Ba mẹ kể lúc bé bị ốm, ai đã chăm sóc bé.","Bé đóng vai bác sĩ khám bệnh cho gấu bông.","Bé kể lại lời dặn của bác sĩ khi bị cảm.","Bé vẽ một tấm thiệp cảm ơn bác sĩ."],"Mình làm gì để ít bị ốm?","life-dentist"],["⚡","An toàn với điện","Bé biết tránh xa điện để không bị điện giật.",["Ba mẹ chỉ các ổ cắm và dây điện trong nhà.","Bé nhắc lại: con không tự cắm hoặc rút phích điện.","Bé vẽ dấu hiệu nguy hiểm bên cạnh hình ổ điện.","Bé nhớ: thấy dây điện bị hở thì báo người lớn."],"Vì sao không được thả diều gần đường dây điện?","life-safe"],["🏆","Nhìn lại năm học","Bé tự hào về những gì mình đã cố gắng.",["Bé chọn ba bài làm hoặc bức tranh đẹp nhất trong năm học.","Bé kể vì sao mình chọn chúng.","Bé nói một điều muốn cố gắng hơn ở lớp 3.","Cả nhà cùng làm một chiếc huy chương giấy tặng bé."],"Mùa hè này con muốn học thêm điều gì?"]],y=[["🗂️","Kế hoạch học tập tuần","Bé tự lập kế hoạch học tập cho một tuần.",["Bé kẻ một bảng bảy ngày trên tờ giấy.","Bé ghi giờ học bài, giờ chơi và giờ đọc sách cho mỗi ngày.","Ba mẹ góp ý để kế hoạch vừa sức.","Cuối mỗi ngày, bé tô màu ô việc đã làm."],"Nếu một ngày chưa làm đúng kế hoạch, con sẽ làm gì?","life-routine"],["🏫","Tự hào về trường em","Bé tìm hiểu và giới thiệu về ngôi trường của mình.",["Bé kể tên trường, tên lớp và tên thầy cô chủ nhiệm.","Bé kể những hoạt động thường có ở trường.","Ba mẹ hỏi bé về bạn bè ở lớp mới.","Bé viết hoặc vẽ ba điều mình tự hào về trường."],"Con muốn góp sức làm gì cho lớp mình?"],["🧑‍🤝‍🧑","Làm việc nhóm","Bé tập phối hợp với người khác để làm xong một việc.",["Cả nhà chọn một việc chung: xếp lại giá sách hoặc ghép một bức tranh.","Mỗi người nhận một phần việc.","Mọi người lắng nghe ý kiến của nhau.","Làm xong, mỗi người nói điều mình học được."],"Khi làm nhóm, nếu bạn có ý kiến khác, con sẽ làm gì?"],["🔍","Em là duy nhất","Bé hiểu mỗi người có nét riêng đáng quý.",["Cả nhà cùng kể nét riêng của mỗi người: nét chữ, giọng nói, sở thích.","Bé viết ba điều làm mình khác các bạn.","Bé nói điều mình quý ở một người bạn khác mình.","Bé tập nói: Mỗi người một vẻ, ai cũng đáng quý."],"Vì sao không nên chê bai bạn khác mình?"],["💭","Điều em lo lắng","Bé chia sẻ nỗi lo và tìm cách vượt qua.",["Bé viết hoặc vẽ một điều làm mình lo lắng.","Ba mẹ lắng nghe, không chê cười.","Cả nhà cùng nghĩ hai cách giúp bé bớt lo.","Bé bỏ tờ giấy vào một chiếc hộp tâm sự."],"Khi lo lắng, con muốn tâm sự với ai?","life-feel"],["🗣️","Tự tin nói trước mọi người","Bé tập nói rõ ràng, tự tin trước cả nhà.",["Bé chọn một chủ đề: con vật, món ăn hoặc trò chơi yêu thích.","Bé chuẩn bị ba câu giới thiệu.","Bé đứng thẳng, nhìn mọi người và nói to, rõ ràng.","Cả nhà vỗ tay và khen một điều bé làm tốt."],"Lúc đứng nói trước cả nhà, con thấy thế nào?"],["🎯","Mục tiêu nhỏ của em","Bé đặt một mục tiêu nhỏ và cố gắng làm được.",["Bé chọn một mục tiêu cho tuần này, ví dụ đọc mười trang sách.","Bé chia mục tiêu thành từng việc nhỏ cho mỗi ngày.","Bé đánh dấu mỗi ngày đã làm.","Cuối tuần, bé kể mình đã cố gắng thế nào."],"Điều gì giúp con không bỏ cuộc?"],["🧺","Tự giặt khăn và tất","Bé tự giặt những đồ nhỏ của mình.",["Bé cho khăn mặt hoặc đôi tất vào chậu nước.","Bé xoa xà phòng và vò nhẹ.","Bé xả nước sạch cho hết bọt.","Bé vắt khô và phơi lên dây."],"Con còn tự làm được việc gì cho bản thân?","life-tidy"],["🤞","Giữ lời hứa","Bé hiểu vì sao cần giữ lời hứa với bạn bè.",["Ba mẹ kể một câu chuyện về người biết giữ lời hứa.","Bé kể một lần mình đã giữ lời hứa.","Bé nghĩ xem cần làm gì khi không thể giữ lời hứa.","Bé hứa một việc nhỏ với bạn và cố gắng làm đúng."],"Khi bạn không giữ lời hứa, con cảm thấy thế nào?"],["🕊️","Làm lành với bạn","Bé biết cách làm lành sau khi giận bạn.",["Bé kể một lần giận bạn và vì sao.","Ba mẹ và bé đóng vai, nói cảm xúc của mình bằng lời nhẹ nhàng.","Bé tập nói lời xin lỗi và lắng nghe bạn.","Bé nghĩ một việc vui để làm cùng bạn sau khi làm lành."],"Làm lành xong, con và bạn thấy thế nào?","life-feel"],["📝","Thư cảm ơn thầy cô","Bé viết vài dòng cảm ơn thầy cô nhân ngày 20 tháng 11.",["Bé nhớ lại một việc thầy cô đã giúp mình.","Bé viết ba câu cảm ơn lên tấm thiệp.","Bé trang trí thiệp bằng hình vẽ.","Bé tặng thiệp cho thầy cô."],"Con học được điều gì quý nhất từ thầy cô?","art-collage"],["📖","Góc đọc sách","Bé tạo một góc đọc sách và đọc cùng ba mẹ.",["Bé chọn một góc nhà yên tĩnh, có đủ ánh sáng.","Bé xếp những quyển sách mình có vào một chỗ.","Bé và ba mẹ cùng đọc một câu chuyện trong mười lăm phút.","Bé kể về nhân vật mình thích."],"Câu chuyện hôm nay dạy con điều gì?"],["⏱️","Làm việc đúng giờ","Bé tập làm xong việc trong thời gian đã hẹn.",["Bé chọn một việc: làm bài hoặc dọn bàn học.","Bé đoán việc đó mất bao nhiêu phút.","Ba mẹ bấm giờ, bé làm việc.","Bé so sánh thời gian thật với thời gian mình đã đoán."],"Làm gì để con không bị trễ giờ?","life-routine"],["💰","Cần và muốn","Bé phân biệt đồ mình cần và đồ mình chỉ muốn có.",["Bé viết tên năm món đồ mình thích.","Bé xếp mỗi món vào cột Cần hoặc cột Muốn.","Ba mẹ kể cách gia đình lựa chọn khi mua sắm.","Bé đặt một mục tiêu để dành tiền cho món đồ mình muốn."],"Trong năm món đồ ấy, món nào con thật sự cần?","life-needs"],["🔥","Phòng cháy trong nhà","Bé biết cách phòng cháy và thoát ra ngoài an toàn.",["Ba mẹ chỉ những thứ dễ gây cháy: bếp, ổ điện, bật lửa.","Bé nhắc lại: không nghịch lửa, diêm và bật lửa.","Cả nhà vẽ đường thoát ra ngoài khi có cháy.","Bé nhớ số cứu hỏa 114 và tập cúi thấp người khi đi."],"Khi có khói, vì sao mình phải cúi thấp người?","life-sos"],["🌐","Dùng máy tính an toàn","Bé biết vài quy tắc khi dùng máy tính và điện thoại.",["Ba mẹ và bé thống nhất thời gian dùng máy mỗi ngày.","Bé nhắc lại: không cho người lạ biết tên trường và địa chỉ nhà.","Bé hỏi ba mẹ trước khi bấm vào một đường liên kết lạ.","Bé viết các quy tắc lên giấy và dán gần máy."],"Thấy điều gì làm con sợ trên mạng, con sẽ làm gì?","it-netsafe"],["🏃","Vận động mỗi ngày","Bé tập thể dục tại nhà mười lăm phút.",["Bé khởi động bằng cách xoay cổ tay, cổ chân.","Bé nhảy tại chỗ một phút rồi nghỉ, làm lại ba lần.","Bé tập vươn vai và hít thở sâu.","Bé uống nước và nghỉ ngơi."],"Sau khi tập, cơ thể con thấy thế nào?"],["🍎","Bữa sáng lành mạnh","Bé biết chọn bữa sáng tốt cho sức khỏe.",["Bé kể các món mình hay ăn sáng.","Ba mẹ và bé chia món ăn thành nhóm: tinh bột, thịt cá trứng, rau quả, sữa.","Bé lên thực đơn ba bữa sáng cho tuần tới.","Bé tự nhắc mình ăn sáng trước khi đi học."],"Nếu không ăn sáng, khi học con sẽ thấy thế nào?","life-chef"],["🌳","Cây gia đình","Bé tìm hiểu các thế hệ trong gia đình.",["Bé vẽ một cái cây lớn trên giấy.","Bé ghi tên mình và tên người thân lên các cành cây.","Ba mẹ kể về ông bà hoặc người thân lớn tuổi.","Bé treo tranh cây gia đình ở chỗ dễ thấy."],"Con biết thêm điều gì về người thân lớn tuổi?"],["🧾","Chia sẻ việc nhà","Bé cùng cả nhà chia việc nhà hợp lí.",["Cả nhà kể các việc nhà cần làm trong một ngày.","Mỗi người nhận một việc phù hợp.","Bé nhận hai việc vừa sức và làm suốt cả tuần.","Cuối tuần, cả nhà nói lời cảm ơn nhau."],"Việc nhà nào con làm tốt nhất?","life-dishes"],["🎆","Tết quê em","Bé tìm hiểu cách đón Tết ở quê mình.",["Ba mẹ kể về Tết ở quê ngày xưa.","Bé hỏi về món ăn và trò chơi ngày Tết.","Bé vẽ tranh về Tết theo lời kể.","Bé tập viết một lời chúc Tết gửi người thân."],"Tết ngày xưa khác Tết bây giờ ở điều gì?","vn-holiday"],["💌","Quan tâm người cao tuổi","Bé biết quan tâm, giúp đỡ người cao tuổi.",["Bé kể tên một người cao tuổi mà bé quen.","Bé nghĩ ba việc giúp người cao tuổi: lấy nước, nói chậm và rõ, xách giúp đồ nhẹ.","Bé cùng ba mẹ gọi điện hỏi thăm một người cao tuổi.","Bé vẽ một bức tranh để tặng."],"Vì sao mình cần quan tâm, nhường nhịn người cao tuổi?"],["🏞️","Cảnh đẹp đất nước","Bé biết một cảnh đẹp của đất nước Việt Nam.",["Ba mẹ kể hoặc cho bé xem ảnh một cảnh đẹp ở Việt Nam.","Bé nói cảnh đó ở đâu và có gì đẹp.","Bé vẽ lại cảnh đẹp đó.","Bé kể cho người thân nghe về cảnh đẹp ấy."],"Con muốn đến thăm nơi nào nhất?","vn-places"],["🎁","Chia sẻ đồ còn tốt","Bé chọn đồ dùng còn tốt để chia sẻ với người khác.",["Bé chọn quần áo, sách hoặc đồ chơi còn tốt mà mình không dùng nữa.","Bé lau sạch và gấp gọn.","Bé viết một tấm thiệp nhỏ gửi kèm.","Ba mẹ giúp bé gửi đến nơi cần."],"Người nhận được đồ của con sẽ thấy thế nào?","life-kind"],["🌺","Ý nghĩa ngày 8 tháng 3","Bé thể hiện tình cảm với những người phụ nữ thân yêu.",["Ba mẹ kể: ngày 8 tháng 3 là ngày Quốc tế Phụ nữ.","Bé làm một bông hoa giấy hoặc một tấm thiệp.","Bé làm thay một việc nhà cho người mình tặng quà.","Bé nói lời chúc và tặng quà."],"Người ấy thường làm những gì cho con?","art-collage"],["🌿","Các bộ phận của cây","Bé quan sát các bộ phận của cây.",["Bé chọn một cây trong nhà hoặc ngoài sân.","Bé chỉ rễ, thân, lá và hoa hoặc quả nếu có.","Bé vẽ cây và ghi tên các bộ phận.","Bé tưới cây và nói một việc giúp cây khỏe."],"Bộ phận nào giúp cây hút nước?","sci-grow"],["🗑️","Phân loại rác tại nhà","Bé biết chia rác thành rác thực phẩm, rác tái chế và rác khác.",["Ba mẹ và bé chuẩn bị ba túi hoặc ba hộp.","Bé ghi nhãn: rác thực phẩm, rác tái chế, rác khác.","Bé phân loại rác sau bữa ăn.","Bé kể rác tái chế có thể làm thành những gì."],"Vỏ chai nhựa nên bỏ vào loại rác nào?","life-trash"],["🔦","Bóng của đồ vật","Bé quan sát bóng của đồ vật thay đổi theo ánh sáng.",["Bé dùng đèn bàn hoặc đèn điện thoại chiếu vào một món đồ chơi.","Bé đưa đèn lại gần rồi ra xa, xem bóng to hay nhỏ.","Bé làm bóng hình con vật bằng hai bàn tay.","Bé kể khi nào thì có bóng."],"Khi đèn lại gần đồ vật, bóng to lên hay nhỏ đi?","sci-shadow"],["💡","Tiết kiệm điện","Bé biết tắt điện khi không dùng.",["Bé đi quanh nhà tìm đèn, quạt đang bật mà không ai dùng.","Bé nhờ người lớn tắt, hoặc tự tắt công tắc khi tay khô.","Bé làm một tấm biển nhắc: Ra khỏi phòng nhớ tắt đèn.","Bé dán tấm biển cạnh công tắc."],"Tiết kiệm điện giúp gì cho gia đình và Trái Đất?","sci-circuit"],["🎙️","Hỏi chuyện người thân về nghề","Bé tìm hiểu một nghề qua lời kể của người thân.",["Bé chuẩn bị ba câu hỏi về nghề nghiệp.","Bé hỏi một người thân và lắng nghe.","Bé ghi lại hoặc vẽ điều mình nhớ nhất.","Bé kể lại cho cả nhà nghe."],"Nghề đó cần những đức tính gì?"],["🏺","Nghề truyền thống","Bé biết một số nghề truyền thống của Việt Nam.",["Ba mẹ kể về nghề làm gốm, dệt vải, đan lát hoặc làm nón lá.","Bé chọn một nghề và vẽ sản phẩm của nghề đó.","Bé xé giấy thành dải rồi đan thử một tấm nhỏ.","Bé kể vì sao cần giữ gìn nghề truyền thống."],"Nghề truyền thống nào con thấy thú vị nhất?","vn-steps"],["🛒","Đóng vai người bán hàng","Bé hiểu công việc bán hàng và tập tính tiền.",["Bé bày vài món đồ trong nhà làm hàng.","Bé ghi giá cho từng món, ví dụ 2 nghìn đồng, 5 nghìn đồng.","Ba mẹ đóng vai người mua, bé tính tiền và trả lại tiền thừa.","Bé nói lời cảm ơn khách."],"Người bán hàng cần làm gì để khách vui?","play-market"],["🌠","Nghề em mơ ước","Bé kể về nghề mình mơ ước.",["Bé nói nghề mình thích và vì sao.","Bé kể công việc hằng ngày của nghề đó.","Bé vẽ mình khi lớn lên làm nghề đó.","Ba mẹ cùng bé nghĩ những điều cần học từ bây giờ."],"Muốn làm nghề đó, con cần chăm chỉ học gì?"],["🌊","Phòng tránh đuối nước","Bé biết các quy tắc an toàn khi ở gần nước.",["Ba mẹ kể những nơi nguy hiểm: ao, hồ, sông, suối, bể nước.","Bé nhắc lại: không đi bơi một mình, chỉ bơi khi có người lớn trông.","Bé tập kêu cứu: hô thật to và gọi người lớn, không tự nhảy xuống nước cứu bạn.","Bé vẽ tranh nhắc mọi người phòng tránh đuối nước."],"Thấy bạn bị rơi xuống nước, con nên làm gì?","life-safe"],["📔","Sổ tay lớn khôn","Bé ghi lại những điều mình đã học và đã làm được.",["Bé gấp một quyển sổ nhỏ bằng giấy.","Bé viết ba điều mình đã học được trong năm học.","Bé viết hai điều muốn làm trong hè.","Cả nhà viết một lời khen vào trang cuối."],"Điều gì làm con thấy mình đã lớn hơn?"]],p=[["🗓️","Quản lí thời gian","Bé tự sắp xếp thời gian học và chơi hợp lí.",["Bé ghi lại các việc mình đã làm vào chiều hôm qua.","Bé đánh dấu việc nào quan trọng, việc nào có thể làm sau.","Bé lập thời gian biểu mới cho buổi chiều.","Bé làm thử trong ba ngày rồi sửa lại cho phù hợp."],"Việc nào làm con mất nhiều thời gian nhất?","life-routine"],["🙌","Em là thành viên của lớp","Bé tìm cách đóng góp cho tập thể lớp.",["Bé kể các việc chung của lớp: trực nhật, chăm cây, giữ tủ sách.","Bé chọn một việc mình có thể nhận làm.","Bé tập nói ý kiến trước cả nhà như khi họp lớp.","Bé nói với thầy cô việc mình muốn nhận."],"Con sẽ làm gì để lớp mình vui hơn?"],["📚","Cách học nhớ lâu","Bé thử một cách học giúp nhớ lâu hơn.",["Bé chọn một bài vừa học ở lớp.","Bé đọc và gạch chân ba ý chính bằng bút chì.","Bé gấp sách lại và kể lại cho ba mẹ nghe.","Bé ghi một câu hỏi về điều mình chưa hiểu."],"Cách học nào giúp con nhớ lâu nhất?"],["🔭","Khám phá khả năng của em","Bé nhận ra khả năng của mình và điều muốn rèn thêm.",["Bé viết ba việc mình làm tốt và ba việc muốn làm tốt hơn.","Ba mẹ kể một lần thấy bé rất cố gắng.","Bé chọn một kĩ năng để luyện trong tháng này.","Bé ghi kĩ năng đó và dán ở góc học tập."],"Con cần ai giúp để luyện kĩ năng ấy?"],["🌡️","Nhiệt kế cảm xúc","Bé biết gọi tên và chia sẻ cảm xúc của mình.",["Bé vẽ một nhiệt kế cảm xúc từ rất buồn đến rất vui.","Mỗi tối, bé đánh dấu cảm xúc của ngày hôm đó.","Bé kể chuyện gì đã làm mình vui hoặc buồn.","Cả nhà cùng tìm một việc giúp bé thấy dễ chịu hơn."],"Tuần này, ngày nào con thấy vui nhất?","life-feel"],["🛡️","Cơ thể em là của em","Bé biết tôn trọng và bảo vệ cơ thể mình.",["Ba mẹ nhắc: vùng cơ thể được đồ bơi che lại là vùng riêng tư, không ai được chạm vào.","Bé tập nói to: Không được chạm vào tôi!","Bé kể tên ba người lớn đáng tin cậy để kể khi gặp chuyện.","Ba mẹ hứa luôn lắng nghe và không trách bé."],"Nếu ai làm con thấy khó chịu, con sẽ kể với ai?","life-sos"],["🌈","Em biết vượt khó","Bé tập kiên trì khi gặp việc khó.",["Bé chọn một việc khó: một bài toán, buộc dây giày hoặc một bức tranh ghép.","Bé thử làm trong mười phút, không bỏ cuộc.","Nếu chưa làm được, bé hỏi gợi ý thay vì nhờ làm hộ.","Bé kể cảm giác của mình khi làm được."],"Lần tới gặp việc khó, con sẽ nói gì với bản thân?"],["🍌","Tự chuẩn bị bữa phụ","Bé tự chuẩn bị một bữa phụ lành mạnh không cần dùng bếp.",["Bé rửa tay và rửa sạch quả.","Bé bóc chuối hoặc quýt rồi xếp ra đĩa.","Bé rót một cốc sữa hoặc nước lọc.","Bé dọn sạch chỗ mình vừa làm."],"Bữa phụ nào tốt cho sức khỏe hơn bánh kẹo?","life-chef"],["👂","Lắng nghe bạn nói","Bé tập lắng nghe khi người khác nói.",["Ba mẹ kể một chuyện ngắn trong hai phút.","Bé lắng nghe, nhìn người nói và không ngắt lời.","Bé kể lại ý chính của câu chuyện.","Đổi vai: bé kể chuyện, ba mẹ lắng nghe."],"Khi được lắng nghe, con cảm thấy thế nào?"],["💬","Lời tử tế trên mạng","Bé biết cư xử lịch sự khi nhắn tin, bình luận.",["Ba mẹ đọc hai tin nhắn: một tin lịch sự, một tin làm bạn buồn.","Bé chỉ ra tin nào nên gửi và vì sao.","Bé tập viết lại tin nhắn chưa hay cho tử tế hơn.","Bé nhắc lại: thấy bạn bị chê bai trên mạng thì báo người lớn."],"Trước khi gửi tin nhắn, con nên tự hỏi điều gì?","it-netsafe"],["🌻","Tri ân thầy cô","Bé thể hiện lòng biết ơn thầy cô bằng lời nói và việc làm.",["Bé viết một lá thư ngắn kể một kỉ niệm với thầy cô.","Bé đặt mục tiêu học tốt một môn để thầy cô vui.","Bé cùng ba mẹ trang trí lá thư.","Bé gửi thư tặng thầy cô nhân ngày 20 tháng 11."],"Vì sao chúng ta có ngày Nhà giáo Việt Nam?"],["🗳️","Góp ý xây dựng lớp","Bé tập đưa ra ý kiến lịch sự để lớp tốt hơn.",["Bé nghĩ một điều muốn lớp mình tốt hơn.","Bé viết ý kiến theo cách: Em thấy, em đề nghị.","Bé tập nói ý kiến trước ba mẹ.","Bé gửi ý kiến cho thầy cô hoặc lớp trưởng."],"Nếu bạn không đồng ý với ý kiến của con, con sẽ làm gì?"],["🐖","Chi tiêu thông minh","Bé tập lập kế hoạch dùng tiền để dành.",["Bé kể những khoản tiền mình hay tiêu: quà sáng, đồ dùng học tập.","Bé vẽ tiền trên giấy và chia thành ba phần: tiêu, để dành, chia sẻ.","Bé đặt mục tiêu để dành cho một món đồ cần thiết.","Bé ghi số tiền để dành vào một quyển sổ nhỏ."],"Vì sao nên để dành một phần tiền?","life-save"],["🧹","Phòng của em gọn gàng","Bé tự dọn dẹp và sắp xếp chỗ ở của mình.",["Bé chia đồ đạc thành nhóm: sách, quần áo, đồ chơi.","Bé xếp mỗi nhóm vào một chỗ riêng.","Bé chọn những đồ không dùng nữa để chia sẻ hoặc tái chế.","Bé hẹn mỗi tối dành năm phút dọn lại."],"Chỗ ở gọn gàng giúp con tìm đồ nhanh hơn thế nào?","life-tidy"],["🩹","Khi bị trầy xước nhẹ","Bé biết làm gì khi bị trầy xước nhẹ.",["Ba mẹ kể các bước khi bị xước nhẹ: rửa bằng nước sạch, lau khô, dán băng.","Bé tập dán băng cho gấu bông, có thể dùng mẩu giấy thay băng.","Bé nhắc lại: vết thương chảy nhiều máu thì gọi người lớn ngay.","Bé nhớ số cấp cứu 115."],"Bị đứt tay chảy nhiều máu, việc đầu tiên con cần làm là gì?","life-sos"],["🔐","Giữ kín thông tin riêng","Bé biết bảo vệ thông tin cá nhân khi dùng mạng.",["Bé kể những thông tin riêng: họ tên đầy đủ, địa chỉ, trường học, mật khẩu.","Bé nhắc lại: không gửi những thông tin này cho người lạ.","Ba mẹ giải thích thế nào là mật khẩu mạnh và vì sao không nói cho ai.","Bé biết tắt máy và báo ba mẹ khi gặp tin nhắn lạ."],"Vì sao không nên đưa ảnh có địa chỉ nhà lên mạng?","it-netsafe"],["🏸","Thể thao cùng gia đình","Bé vận động cùng cả nhà mười lăm phút.",["Cả nhà chọn một trò vận động an toàn: nhảy dây, tập theo nhạc hoặc chơi bóng mềm.","Mọi người khởi động tay chân trước.","Cả nhà cùng chơi mười phút, ai mệt thì nghỉ.","Bé uống nước và kể cảm giác sau khi tập."],"Con muốn tập đều đặn môn thể thao nào?"],["📵","Buổi tối không màn hình","Bé dành một buổi tối không dùng ti vi, điện thoại.",["Cả nhà hẹn một giờ không dùng màn hình.","Bé chọn hoạt động thay thế: đọc sách, chơi cờ hoặc vẽ tranh.","Bé để điện thoại và máy tính bảng ở xa chỗ ngồi.","Cuối buổi, cả nhà kể điều vui nhất."],"Không dùng màn hình, con đã làm được việc gì thú vị?"],["🏠","Nét đẹp gia đình em","Bé tìm hiểu nét đẹp riêng của gia đình mình.",["Bé hỏi ba mẹ về một thói quen tốt của gia đình, như cùng ăn cơm tối.","Bé ghi lại thói quen đó.","Bé vẽ tranh cả nhà đang cùng làm việc đó.","Bé nói mình sẽ giữ gìn thói quen ấy thế nào."],"Con muốn gia đình mình có thêm thói quen tốt nào?"],["👵","Chuyện ngày xưa","Bé nghe người lớn kể chuyện ngày xưa.",["Bé chuẩn bị câu hỏi: hồi nhỏ ông bà hoặc ba mẹ chơi trò gì.","Bé hỏi và lắng nghe câu trả lời.","Bé thử chơi một trò chơi dân gian vừa được kể.","Bé viết vài dòng về điều mình thích nhất."],"Trò chơi ngày xưa khác trò chơi bây giờ thế nào?"],["🧧","Lời chúc đầu năm","Bé hiểu ý nghĩa của lời chúc và phong bao mừng tuổi ngày Tết.",["Ba mẹ kể: phong bao mừng tuổi là lời chúc may mắn đầu năm.","Bé tập nói lời cảm ơn và lời chúc khi được mừng tuổi.","Bé lập kế hoạch dùng tiền mừng tuổi: để dành, mua sách, chia sẻ.","Bé ghi kế hoạch vào sổ nhỏ."],"Con sẽ dùng tiền mừng tuổi vào việc gì có ích?","vn-holiday"],["🏛️","Di tích quê em","Bé tìm hiểu một di tích lịch sử ở nơi mình sống.",["Ba mẹ kể về một ngôi đình, ngôi chùa, đền thờ hoặc tượng đài gần nơi mình sống.","Bé tìm hiểu di tích đó gắn với ai hoặc với sự kiện gì.","Bé vẽ di tích và viết hai câu giới thiệu.","Bé nói những việc nên làm để giữ gìn di tích."],"Khi đến thăm di tích, mình cần cư xử thế nào?","vn-places"],["🚮","Khu phố sạch đẹp","Bé đề xuất việc làm để giữ gìn nơi mình sống.",["Bé nhớ lại những chỗ sạch và chưa sạch gần nhà.","Bé nghĩ hai việc trẻ em có thể làm: không xả rác, nhắc bạn bỏ rác đúng chỗ.","Bé vẽ một tấm áp phích kêu gọi giữ khu phố sạch.","Bé dán áp phích ở nhà và kể cho bạn nghe."],"Một mình con có thể làm khu phố sạch hơn không, vì sao?","life-trash"],["🤲","Chung tay giúp người khó khăn","Bé biết chia sẻ với người gặp khó khăn.",["Ba mẹ kể về những người gặp khó khăn sau bão lũ hoặc khi ốm đau.","Bé nghĩ những việc mình có thể làm: góp sách, góp quần áo còn tốt.","Bé chọn và gói gọn đồ muốn góp.","Ba mẹ giúp bé gửi đồ qua nhà trường hoặc nơi nhận quyên góp."],"Vì sao chia sẻ làm cả người cho và người nhận đều vui?","life-kind"],["💐","Việc nhà là việc chung","Bé hiểu việc nhà là việc chung của mọi người.",["Bé để ý xem trong một ngày, mẹ hoặc người thân đã làm những việc gì cho cả nhà.","Bé ghi lại ba việc đó.","Bé làm thay một việc và tặng một lời chúc nhân ngày 8 tháng 3.","Bé nói: mọi người trong nhà đều nên chia sẻ việc nhà."],"Việc nhà có phải chỉ là việc của phụ nữ không?"],["💧","Nước biến đi đâu","Bé quan sát nước bay hơi nhanh hơn khi có nắng.",["Bé đổ một ít nước vào hai cái đĩa nhỏ.","Bé đặt một đĩa chỗ có nắng, một đĩa trong bóng râm.","Sau vài giờ, bé so sánh lượng nước còn lại ở hai đĩa.","Bé kể nước đã biến đi đâu."],"Vì sao đĩa để chỗ nắng lại khô nhanh hơn?","sci-states"],["🌏","Bớt rác nhựa","Bé tìm cách dùng ít đồ nhựa dùng một lần.",["Bé đếm số túi ni lông và chai nhựa trong nhà sau một ngày.","Bé nghĩ đồ dùng thay thế: túi vải, bình nước cá nhân.","Bé chọn một thói quen mới, như mang bình nước riêng đi học.","Bé nhắc cả nhà cùng làm theo."],"Rác nhựa có thể gây hại gì cho biển và các con vật?","life-trash"],["🐘","Bảo vệ động vật hoang dã","Bé biết vì sao cần bảo vệ động vật hoang dã.",["Ba mẹ kể về một loài vật quý của Việt Nam như voi, voọc hoặc rùa biển.","Bé tìm hiểu nơi sống và thức ăn của loài vật đó.","Bé vẽ tranh kêu gọi bảo vệ loài vật ấy.","Bé nói một việc trẻ em có thể làm để bảo vệ động vật."],"Vì sao không nên mua đồ làm từ động vật hoang dã?","sci-foodchain"],["🧅","Vườn rau trong cốc","Bé trồng lại gốc hành lá để hành mọc lại.",["Bé giữ lại phần gốc có rễ của vài cây hành lá sau bữa ăn.","Bé đặt gốc hành vào cốc có một chút nước.","Bé để cốc chỗ có ánh sáng và thay nước mỗi ngày.","Bé ghi lại chiều cao của lá hành mỗi ngày."],"Cây hành cần những gì để mọc lại?","sci-grow"],["🏗️","Nghề nào cũng đáng quý","Bé hiểu mọi nghề đều có ích cho xã hội.",["Bé kể tên mười nghề mà bé biết.","Bé ghép mỗi nghề với một việc giúp ích cho mọi người.","Bé chọn một nghề ít được để ý và nói lời cảm ơn những người làm nghề đó.","Bé vẽ sơ đồ các nghề quanh em."],"Nếu không có người làm nghề ấy, cuộc sống sẽ ra sao?"],["🔧","Người thợ sửa chữa","Bé tìm hiểu công việc của người thợ và thử sửa một đồ dùng đơn giản.",["Bé tìm một đồ dùng bị hỏng nhẹ: quyển sách bị bong gáy hoặc hộp giấy bị bung.","Bé cùng ba mẹ dùng hồ dán hoặc băng dính để sửa.","Bé kể những dụng cụ người thợ hay dùng.","Bé nói vì sao người thợ cần làm việc cẩn thận."],"Đồ dùng bị hỏng, mình nên sửa hay vứt đi?"],["🗺️","Nghề ở quê em","Bé biết những nghề phổ biến ở nơi mình sống.",["Ba mẹ kể những nghề nhiều người làm ở nơi mình sống.","Bé chọn một nghề và tìm hiểu sản phẩm của nghề đó.","Bé vẽ sản phẩm và viết hai câu giới thiệu.","Bé kể nghề đó giúp ích cho quê hương thế nào."],"Con tự hào về sản phẩm nào của quê mình?","vn-steps"],["🎤","Phóng viên nhí","Bé thử làm phóng viên, hỏi chuyện người thân.",["Bé chọn đề tài: món ăn yêu thích của mỗi người.","Bé chuẩn bị ba câu hỏi.","Bé hỏi từng người và ghi câu trả lời vào giấy.","Bé đọc bản tin ngắn cho cả nhà nghe."],"Một phóng viên giỏi cần những kĩ năng gì?"],["⛈️","An toàn khi mưa bão","Bé biết cách giữ an toàn khi có mưa to, sấm sét.",["Ba mẹ kể những nguy hiểm khi mưa bão: cây đổ, nước ngập, sấm sét.","Bé nhắc lại: khi có sấm sét thì ở trong nhà, không đứng dưới gốc cây to.","Bé nhắc lại: tránh xa chỗ nước ngập và dây điện bị đứt.","Cả nhà để đèn pin hoặc điện thoại đã sạc ở chỗ dễ lấy."],"Đi đường gặp mưa to có sấm sét, con nên làm gì?","sci-weather"],["🎓","Nhìn lại năm lớp 4","Bé nhìn lại năm học và đặt mục tiêu cho năm sau.",["Bé viết ba điều đáng nhớ nhất của năm lớp 4.","Bé viết một điều mình đã tiến bộ.","Bé đặt một mục tiêu cho năm lớp 5.","Cả nhà viết lời chúc vào mặt sau tờ giấy."],"Con muốn cảm ơn ai vì đã giúp con trong năm học?"]],k=[["🧭","Năm cuối cấp tiểu học","Bé chuẩn bị tinh thần cho năm học cuối cấp tiểu học.",["Bé viết ba điều mong muốn ở năm lớp 5.","Bé nghĩ mình sẽ làm gương cho các em lớp dưới thế nào.","Bé cùng ba mẹ lập kế hoạch học tập theo tuần.","Bé chọn giờ ôn bài cố định mỗi tối."],"Là anh chị lớn nhất trường, con muốn làm gì cho các em?","life-routine"],["🗂️","Sổ tay học tập","Bé tạo sổ tay ghi bài và việc cần làm.",["Bé chọn một quyển vở làm sổ tay.","Bé chia sổ thành các mục: bài tập, việc cần làm, điều mới học.","Bé ghi các việc của tuần này vào sổ.","Mỗi tối, bé gạch những việc đã xong."],"Sổ tay giúp con nhớ việc như thế nào?"],["🤝","Làm trưởng nhóm","Bé tập điều khiển một nhóm cùng làm việc.",["Cả nhà chọn một việc chung: dọn bàn ăn hoặc xếp lại giá sách.","Bé làm trưởng nhóm và chia việc cho từng người.","Bé nhắc nhở nhẹ nhàng và giúp người làm chậm hơn.","Cuối buổi, bé cảm ơn và nhận xét từng người."],"Một trưởng nhóm tốt cần có những điều gì?"],["🪞","Tự tin là chính mình","Bé biết tự tin và chăm sóc bản thân đúng cách.",["Bé viết năm từ tốt đẹp để nói về mình.","Bé kể một thói quen chăm sóc bản thân hằng ngày.","Ba mẹ và bé nói về việc mỗi người mỗi khác và ai cũng đáng quý.","Bé chọn một thói quen tốt mới: ngủ sớm, ăn rau hoặc vận động."],"Điều gì làm con thấy tự tin?"],["🌦️","Làm chủ cảm xúc","Bé biết cách vượt qua cảm xúc mạnh.",["Bé kể một chuyện làm mình rất buồn hoặc rất giận.","Bé viết ra suy nghĩ của mình lúc đó.","Bé và ba mẹ tìm ba cách để bình tĩnh lại: thở sâu, đi lại, viết nhật kí.","Bé chọn một cách và dùng khi cần."],"Khi buồn, con tin tưởng chia sẻ với ai?","life-feel"],["💡","Suy nghĩ tích cực","Bé tập nhìn mặt tốt khi gặp chuyện không như ý.",["Ba mẹ kể một chuyện không như ý, như trời mưa nên không đi chơi được.","Bé tìm hai điều tốt trong chuyện đó.","Bé tập đổi câu: Mình không làm được, thành câu: Mình chưa làm được.","Bé dùng câu nói mới đó trong cả tuần."],"Câu nói nào giúp con có thêm động lực?"],["🏁","Kế hoạch rèn một kĩ năng","Bé lập kế hoạch luyện một kĩ năng trong bốn tuần.",["Bé chọn một kĩ năng: gấp quần áo, gõ bàn phím hoặc đọc diễn cảm.","Bé chia kĩ năng thành bốn bước nhỏ, mỗi tuần một bước.","Bé luyện bước đầu tiên trong mười phút.","Bé ghi lại sự tiến bộ vào sổ tay."],"Con sẽ tự thưởng điều gì khi luyện xong kĩ năng?"],["🧺","Tự lo việc cá nhân","Bé tự làm các việc cá nhân mà không cần nhắc.",["Bé liệt kê các việc cá nhân mỗi ngày: gấp quần áo, chuẩn bị cặp, phơi khăn.","Bé kẻ một bảng để tự đánh dấu.","Bé tự làm và tự đánh dấu trong ba ngày.","Bé cùng ba mẹ xem lại bảng."],"Việc nào con đã tự làm mà không cần ai nhắc?","life-tidy"],["🫂","Tình bạn đẹp","Bé hiểu thế nào là một tình bạn tốt.",["Bé viết ba điều một người bạn tốt sẽ làm.","Bé viết ba điều không nên làm với bạn.","Bé kể một kỉ niệm đẹp với bạn thân.","Bé viết một lời nhắn cảm ơn bạn."],"Nếu bạn rủ làm điều sai, con sẽ từ chối thế nào?"],["🛑","Nói không với bắt nạt","Bé biết cách ứng xử khi thấy bạn bị bắt nạt.",["Ba mẹ kể một tình huống bắt nạt ở trường hoặc trên mạng.","Bé nói cảm xúc của bạn bị bắt nạt.","Bé tập ba việc: không hùa theo, ở bên bạn, báo thầy cô hoặc người lớn.","Bé viết một câu động viên bạn bị bắt nạt."],"Vì sao báo cho người lớn không phải là mách lẻo?","it-netsafe"],["🎼","Tiết mục tặng thầy cô","Bé chuẩn bị một tiết mục nhỏ tặng thầy cô.",["Bé chọn một bài hát, bài thơ hoặc câu chuyện về thầy cô.","Bé tập cho thuộc và tập biểu diễn.","Bé biểu diễn cho cả nhà xem và nghe góp ý.","Bé biểu diễn tặng thầy cô nhân ngày 20 tháng 11."],"Con muốn gửi tới thầy cô điều gì qua tiết mục?","mus-rhythm"],["⭐","Làm gương cho em nhỏ","Bé biết giúp đỡ và làm gương cho các em nhỏ.",["Bé nghĩ một việc tốt có thể làm cho em nhỏ: đọc truyện, dạy gấp giấy.","Bé chuẩn bị việc đó cùng ba mẹ.","Bé làm cùng em nhỏ trong nhà, hoặc đóng vai cùng ba mẹ.","Bé kể lại em nhỏ đã vui thế nào."],"Làm anh chị, con cần kiên nhẫn như thế nào?"],["💵","Ngân sách nhỏ","Bé tập lập ngân sách tiêu dùng cho một tuần.",["Bé giả sử mình có năm mươi nghìn đồng để tiêu trong một tuần.","Bé liệt kê các khoản cần chi và muốn chi.","Bé chia tiền sao cho vẫn còn một phần để dành.","Ba mẹ cùng bé xem ngân sách đã hợp lí chưa."],"Nếu muốn mua một món đồ đắt, con cần làm gì?","life-needs"],["🧠","Xây thói quen tốt","Bé tập một thói quen tốt mỗi ngày trong ba tuần.",["Bé chọn một thói quen: đọc sách mười phút, uống đủ nước hoặc dậy đúng giờ.","Bé vẽ một bảng hai mươi mốt ô.","Mỗi ngày làm được, bé tô màu một ô.","Bé đặt bảng ở nơi dễ thấy."],"Điều gì làm con dễ quên thói quen mới?"],["🧯","Thoát hiểm khi có cháy","Bé biết lối thoát và cách thoát ra ngoài an toàn khi có cháy.",["Cả nhà vẽ sơ đồ nhà và đánh dấu hai lối ra.","Bé tập: cúi thấp người, che mũi miệng bằng khăn, đi theo lối thoát.","Bé nhắc lại: không trốn trong tủ hay gầm giường, không quay lại lấy đồ.","Bé nhớ số cứu hỏa 114 và tập nói rõ địa chỉ nhà."],"Vì sao không được đi thang máy khi có cháy?","life-sos"],["🎮","Dùng thiết bị điện tử thông minh","Bé tự quản lí thời gian dùng thiết bị điện tử.",["Bé ghi lại thời gian mình dùng điện thoại, máy tính trong hai ngày.","Bé cùng ba mẹ đặt giới hạn hợp lí cho mỗi ngày.","Bé nhắc lại việc cần làm khi gặp nội dung xấu: tắt đi và báo ba mẹ.","Bé chọn một hoạt động thay thế khi hết giờ."],"Dùng thiết bị quá lâu có hại gì cho mắt và giấc ngủ?","it-netsafe"],["🪑","Ngồi học đúng tư thế","Bé ngồi học đúng tư thế để bảo vệ mắt và lưng.",["Bé ngồi thẳng lưng, hai bàn chân chạm sàn.","Bé đặt sách cách mắt khoảng ba mươi xăng-ti-mét.","Bé kiểm tra bàn học đã đủ ánh sáng chưa.","Cứ ba mươi phút, bé đứng dậy vươn vai và nhìn ra xa."],"Ngồi sai tư thế lâu ngày có thể gây hại gì?"],["🍱","Thực đơn cân bằng","Bé lập thực đơn một ngày đủ các nhóm chất.",["Bé kể các nhóm chất: chất bột đường, chất đạm, chất béo, vitamin và chất khoáng.","Bé lên thực đơn ba bữa có đủ các nhóm chất.","Ba mẹ góp ý cho thực đơn.","Bé giúp chuẩn bị một món không cần dùng bếp."],"Vì sao không nên ăn quá nhiều đồ ngọt?","life-chef"],["📮","Thư gửi gia đình","Bé viết thư bày tỏ tình cảm với gia đình.",["Bé chọn người nhận thư trong gia đình.","Bé viết lời cảm ơn và kể một kỉ niệm đẹp.","Bé viết một lời hứa sẽ cố gắng.","Bé trao thư tận tay người nhận."],"Nhận được thư, người thân của con đã nói gì?"],["🏡","Họp gia đình","Bé tham gia họp gia đình để bàn việc chung.",["Cả nhà ngồi cùng nhau mười lăm phút.","Mỗi người kể một điều vui và một điều cần giúp trong tuần.","Cả nhà cùng bàn kế hoạch cho cuối tuần.","Bé ghi lại những điều cả nhà đã thống nhất."],"Ý kiến nào của con được cả nhà đồng ý?"],["🎋","Tết cổ truyền","Bé tìm hiểu ý nghĩa các phong tục ngày Tết cổ truyền.",["Bé tìm hiểu ý nghĩa của bánh chưng, câu đối và mâm ngũ quả.","Bé viết ba câu giới thiệu ngày Tết cho một người bạn nước ngoài.","Bé giúp gia đình dọn dẹp, trang trí nhà cửa.","Bé tập viết một câu chúc Tết thật hay."],"Phong tục ngày Tết nào con muốn giữ gìn mãi?","vn-holiday"],["🏛️","Người có công với đất nước","Bé biết ơn những người có công với đất nước.",["Ba mẹ kể về một anh hùng hoặc danh nhân có tên đặt cho một con đường gần nhà.","Bé tìm hiểu người đó đã làm gì cho đất nước.","Bé viết ba câu giới thiệu về người ấy.","Bé nói điều mình sẽ học tập ở người ấy."],"Vì sao nhiều con đường được đặt theo tên các danh nhân?","vn-timeline"],["🙋‍♀️","Tình nguyện viên nhí","Bé lập kế hoạch và làm một việc tình nguyện nhỏ.",["Bé nghĩ một việc tốt cho mọi người: nhặt rác ở sân chung cùng người lớn hoặc góp sách.","Bé lập kế hoạch: làm gì, khi nào, với ai.","Bé đeo găng tay và làm cùng ba mẹ trong khoảng mười lăm phút.","Bé kể lại cảm nghĩ sau khi làm."],"Việc tình nguyện giúp con học được điều gì?","life-kind"],["⚖️","Quyền và bổn phận của trẻ em","Bé biết một số quyền và bổn phận của trẻ em.",["Ba mẹ kể vài quyền của trẻ em: được học tập, được vui chơi, được bảo vệ.","Bé kể bổn phận của mình: kính trọng người lớn, chăm học, giúp việc nhà.","Bé vẽ tranh về một quyền mà bé thấy quan trọng.","Bé nhớ số Tổng đài quốc gia bảo vệ trẻ em là 111."],"Con sẽ làm tốt hơn bổn phận nào của mình?"],["🌷","Bình đẳng trong gia đình","Bé hiểu mọi thành viên đều chia sẻ việc nhà.",["Bé ghi lại ai làm việc gì trong nhà suốt một ngày.","Bé xem việc nhà đã được chia đều chưa.","Bé đề xuất cách chia việc nhà công bằng hơn.","Bé tặng lời chúc ngày 8 tháng 3 kèm một việc làm thay."],"Con trai và con gái có nên cùng làm việc nhà không?"],["🌡️","Chung tay vì Trái Đất","Bé biết vài việc nhỏ giúp giảm biến đổi khí hậu.",["Ba mẹ kể: biến đổi khí hậu làm thời tiết nóng hơn, mưa bão thất thường hơn.","Bé liệt kê việc làm giúp Trái Đất: tiết kiệm điện, trồng cây, đi bộ quãng đường ngắn.","Bé chọn hai việc và làm trong tuần này.","Bé vẽ một tấm áp phích về Trái Đất xanh."],"Việc nhỏ nào của con có thể giúp Trái Đất?","sci-weather"],["🔋","Năng lượng quanh em","Bé tìm hiểu các nguồn năng lượng dùng trong nhà.",["Bé liệt kê đồ dùng chạy bằng điện và đồ dùng chạy bằng pin trong nhà.","Ba mẹ kể: ánh sáng mặt trời và gió có thể tạo ra điện.","Bé tìm những đồ dùng đang cắm điện mà không dùng đến.","Bé nhờ người lớn rút phích điện những đồ dùng đó."],"Vì sao năng lượng mặt trời được gọi là năng lượng sạch?","sci-circuit"],["🌳","Một cây xanh, một tấm lòng","Bé trồng hoặc nhận chăm sóc một cây xanh.",["Bé gieo hạt vào chậu hoặc nhận chăm một cây có sẵn trong nhà.","Bé tìm hiểu cây cần bao nhiêu nước và ánh sáng.","Bé làm một tấm thẻ ghi tên cho cây.","Bé ghi nhật kí chăm cây mỗi tuần."],"Cây xanh mang lại lợi ích gì cho môi trường?","sci-grow"],["🐸","Chuỗi thức ăn","Bé hiểu các loài sinh vật liên quan với nhau qua thức ăn.",["Bé kể một chuỗi thức ăn: cỏ, châu chấu, ếch, rắn.","Bé vẽ chuỗi thức ăn đó bằng các mũi tên.","Bé nghĩ xem nếu mất đi một loài thì chuyện gì sẽ xảy ra.","Bé nói một việc giúp bảo vệ các loài sinh vật."],"Vì sao không nên săn bắt các loài vật bừa bãi?","sci-foodchain"],["💼","Sở thích và nghề nghiệp","Bé tìm mối liên hệ giữa sở thích và nghề nghiệp.",["Bé liệt kê ba sở thích của mình.","Với mỗi sở thích, bé nghĩ hai nghề liên quan.","Bé hỏi ba mẹ những nghề đó cần học những gì.","Bé ghi vào sổ tay nghề mình quan tâm nhất."],"Sở thích nào có thể trở thành nghề của con sau này?"],["🤖","Nghề của tương lai","Bé tìm hiểu những nghề mới gắn với công nghệ.",["Ba mẹ kể vài nghề mới: lập trình viên, kĩ sư người máy, người thiết kế trò chơi.","Bé và ba mẹ nói về những kĩ năng cần có: suy nghĩ logic, sáng tạo, làm việc nhóm.","Bé vẽ một người máy giúp việc nhà theo ý mình.","Bé giới thiệu người máy đó cho cả nhà."],"Con nghĩ nghề nào sẽ cần nhiều người trong tương lai?","it-computer"],["🧑‍🌾","Người lao động quanh em","Bé trân trọng sản phẩm của người lao động.",["Bé chọn một món đồ trong nhà: bát cơm, chiếc áo hoặc quyển sách.","Bé kể những người đã làm ra món đồ đó.","Bé viết lời cảm ơn những người lao động.","Bé hứa giữ gìn đồ dùng cẩn thận."],"Để có bát cơm, cần những ai làm việc?"],["🎙️","Ngày hội nghề nghiệp tại nhà","Bé giới thiệu một nghề như một người làm nghề thật.",["Bé chọn một nghề và tìm hiểu ba điều về nghề đó.","Bé chuẩn bị trang phục và đồ dùng đơn giản có sẵn trong nhà.","Bé đóng vai và giới thiệu về nghề trong ba phút.","Cả nhà đặt câu hỏi, bé trả lời."],"Điều gì khó nhất khi làm nghề đó?"],["🏖️","Kế hoạch hè an toàn","Bé lập kế hoạch nghỉ hè an toàn và bổ ích.",["Bé liệt kê những việc muốn làm trong hè: đọc sách, học bơi cùng người lớn, về thăm quê.","Bé ghi các quy tắc an toàn: không tắm sông suối, không đi chơi xa một mình.","Bé học thuộc địa chỉ nhà và số điện thoại của người thân.","Bé dán kế hoạch hè ở chỗ dễ thấy."],"Khi ở nhà một mình, con cần nhớ những quy tắc nào?","life-safe"],["🎓","Tạm biệt tiểu học","Bé nhìn lại năm năm tiểu học và sẵn sàng lên lớp 6.",["Bé viết năm kỉ niệm đẹp nhất thời tiểu học.","Bé viết lời cảm ơn thầy cô và bạn bè.","Bé viết ba điều mong muốn ở trường mới.","Cả nhà chúc mừng bé học xong bậc tiểu học."],"Lên lớp 6, con muốn thay đổi điều gì ở bản thân?"]],i=(n,h)=>h.map(([c,a,o,B,v,t],g)=>({grade:n,week:g+1,theme:u[g],icon:c,title:a,goal:o,steps:B,ask:v,...t?{game:t}:{}})),s=[1,2,3,4,5],m={1:i(1,l),2:i(2,b),3:i(3,y),4:i(4,p),5:i(5,k)},q=(n,h)=>{var c;return(c=m[n])==null?void 0:c[h-1]},x=n=>Math.max(1,Math.min(5,(n??6)-5)),C=(n,h)=>`${n}-${h}`,r=n=>`${n.title}.`,e={intro:"Nhiệm vụ tuần này của bé và ba mẹ.",ask:"Ba mẹ hỏi bé.",allTicked:"Đã xong hết các bước rồi. Bấm Đã làm cùng nhau nhé!",done:"Cả nhà đã cùng nhau hoàn thành nhiệm vụ. Tuyệt vời!",sticker:"Bé nhận được một hình dán mới.",print:"Ba mẹ có thể in thẻ nhiệm vụ để dán lên tường."};[...Object.values(e),...s.flatMap(n=>m[n].flatMap(h=>[r(h),h.goal,...h.steps,h.ask]))];export{m as M,C as a,s as b,d as c,e as d,x as g,q as m,r as s};
